// --- Read candidate fields (trim safely) ---
const c = $json;
const get = (k) => (c[k] === undefined || c[k] === null ? '' : String(c[k]).trim());

const name = get('Name');
const email = get('Email');
const degree = get('Degree');
const skills = get('Skills');
const experience = get('Experience');
const availability = get('Availability');

// --- Validate required fields ---
const required = { Name: name, Email: email, Degree: degree, Skills: skills, Experience: experience, Availability: availability };
const missing = Object.keys(required).filter((k) => required[k] === '');
const emailValid = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
if (!emailValid && email !== '') missing.push('Email (invalid format)');

// --- Derived screening metrics ---
// Skills count (comma / slash / semicolon separated)
const skillsCount = skills === '' ? 0 : skills.split(/[,;/]/).map((s) => s.trim()).filter(Boolean).length;
// Experience years — take first number found, supports "4 years", "1.5 yrs", "18 months"
let expYears = 0;
const numMatch = experience.match(/[\d.]+/);
if (numMatch) {
  const val = parseFloat(numMatch[0]);
  expYears = /month/i.test(experience) ? val / 12 : val;
}
// Availability: treat immediate / 1 month as available soon
const availSoon = /(immediate|now|1 month|2 weeks|available)/i.test(availability);

// --- Apply screening rules -> category ---
let category;
let reason;
if (missing.length > 0) {
  category = 'Incomplete';
  reason = 'Missing or invalid required fields: ' + missing.join(', ');
} else if (expYears >= 2 && skillsCount >= 3) {
  category = 'Shortlisted';
  reason = `Strong profile: ${expYears} yr(s) experience, ${skillsCount} skills.`;
} else if (expYears >= 1 || skillsCount >= 2) {
  category = 'On Hold';
  reason = `Partial match: ${expYears} yr(s) experience, ${skillsCount} skills.`;
} else {
  category = 'Rejected';
  reason = `Below threshold: ${expYears} yr(s) experience, ${skillsCount} skills.`;
}

return {
  json: {
    ...c,
    skillsCount,
    experienceYears: Math.round(expYears * 10) / 10,
    availableSoon: availSoon,
    Category: category,
    Status: category,
    Notes: reason,
    ScreenedAt: new Date().toISOString(),
  },
};
